// Fixtures for the picture check tests (ADR 0043): an invented kit, plan and brief for the invented "Fernhill Clay
// Studio", picture files generated by code (solid colour PNGs, no photo), and a picture manifest that passes every
// rule. Each rule test copies the inputs, breaks one thing and checks that only the rule under test notices.
import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import sharp from 'sharp'
import { checkPictures } from '../src/site-pictures/picture-check/check-pictures.js'

// Picture files made by code: name -> [width, height, colour]. The cutout has a clear ground.
const MADE = {
  'hero.png': [400, 200, '#8a5a44'],
  'cutout.png': [240, 240, { r: 40, g: 90, b: 120, alpha: 0.5 }],
  'shelf.png': [200, 200, '#c9b79c'],
  'kiln.png': [200, 200, '#6b4f3a'],
  'initials.png': [150, 150, '#b75436'],
  'icon-light.png': [64, 64, '#222222'],
  'icon-dark.png': [64, 64, '#eeeeee'],
  'band.png': [320, 200, '#3a3a3a'],
  'drawn.png': [240, 180, '#a0b0a0'],
  'drawn-other.png': [240, 180, '#a0b0a1'],
  'hero-small.png': [300, 150, '#8a5a45'],
  'hero-square.png': [400, 400, '#8a5a46']
}

async function makeFiles() {
  const files = {}
  for (const [name, [width, height, background]] of Object.entries(MADE)) {
    const bytes = await sharp({ create: { width, height, channels: 4, background } })
      .png()
      .toBuffer()
    const { width: w, height: h } = await sharp(bytes).metadata()
    files[`out/${name}`] = { sha256: createHash('sha256').update(bytes).digest('hex'), width: w, height: h }
  }
  return files
}

/** path -> { sha256, width, height } of every generated file, the way the bench describes what it wrote. */
export const FILES = await makeFiles()
export const files = () => structuredClone(FILES)

const frame = (id, kind, width, height, extra = {}) => ({
  id,
  kind,
  width,
  height,
  shape: { name: 'any', aspect: Math.round((width / height) * 1000) / 1000 },
  canHide: true,
  twinOf: null,
  fixed: false,
  picture: `images/demo/${id}.jpg`,
  role: null,
  ...extra
})
const slot = (key, width, height) => ({
  key,
  type: 'image',
  sample: `images/demo/${key}.jpg#joomlaImage://local-images/demo/${key}.jpg?width=${width}&height=${height}`,
  fit: { source: { width, height, format: 'jpg' } }
})

