const sha = (c) => c.repeat(64)
/** A frames entry placing the generated file `name`. */
export function placed(frameId, source, name, extra = {}) {
  const f = FILES[`out/${name}`]
  return {
    frame: frameId,
    source,
    file: `out/${name}`,
    width: f.width,
    height: f.height,
    sha256: f.sha256,
    sitePath: `images/tracy-content/${f.sha256}.png`,
    crop: null,
    enlarge: null,
    sharpness: null,
    darkened: false,
    seen: 'what the looker saw',
    reason: 'why this picture',
    ...extra
  }
}
const hidden = (frameId) => ({
  frame: frameId,
  source: 'hide',
  file: null,
  darkened: false,
  seen: null,
  reason: 'no fitting real photo left'
})

/** The colour roles of the fixture icon: the accent in the light theme, the light neutral in the dark one. */
